import re
import secrets

from fastapi import Header, HTTPException, Request
from limits import parse
from limits.storage import MemoryStorage
from limits.strategies import MovingWindowRateLimiter

from utils import config

# Session IDs are generated by the frontend (uuid4().hex). Restricting the format
# keeps them safe to use in folder names and database filters.
SESSION_ID_PATTERN = re.compile(r"^[a-zA-Z0-9_-]{8,64}$")


def require_api_key(x_api_key: str = Header(default="")):
    """Rejects the request unless it carries the configured API key."""
    if not config.API_KEY:
        return  # Auth disabled (local development)
    if not secrets.compare_digest(x_api_key, config.API_KEY):
        raise HTTPException(status_code=401, detail="Invalid or missing API key.")


def get_session_id(x_session_id: str = Header(...)) -> str:
    """Reads and validates the caller's session ID from the X-Session-ID header."""
    if not SESSION_ID_PATTERN.match(x_session_id):
        raise HTTPException(status_code=400, detail="Invalid session ID.")
    return x_session_id


# In-memory counters: fine for a single Render instance (they reset on restart)
_rate = parse(config.RATE_LIMIT)
_rate_limiter = MovingWindowRateLimiter(MemoryStorage())


def rate_limit(request: Request):
    """Allows at most RATE_LIMIT requests per session; returns HTTP 429 beyond that."""
    # All Streamlit users reach the backend from the same Streamlit Cloud server,
    # so limiting by IP would throttle everyone together. Limit per session instead.
    key = request.headers.get("x-session-id") or (request.client.host if request.client else "unknown")
    if not _rate_limiter.hit(_rate, key):
        raise HTTPException(status_code=429, detail="Too many requests. Please wait a minute and try again.")
